package com.apiautomation.clients;
import io.restassured.response.Response;import static io.restassured.RestAssured.given;
public class ApiClient {protected final String baseUrl;public ApiClient(String b){baseUrl=b;} public Response get(String path,String token){var r=given().baseUri(baseUrl);if(token!=null)r.header("Authorization","Bearer "+token);return r.get(path);} public Response post(String path,Object body){return given().baseUri(baseUrl).contentType("application/json").body(body).post(path);}public Response put(String path,Object body,String token){return given().baseUri(baseUrl).contentType("application/json").header("Authorization","Bearer "+token).body(body).put(path);}public Response delete(String path,String token){var r=given().baseUri(baseUrl);if(token!=null)r.header("Authorization","Bearer "+token);return r.delete(path);} }
